    async fn recover(&mut self, io: &mut BusIo<Event>, cut: CutKind, at: Provenance) {
        let reason = match cut {
            CutKind::Incomplete => End::Incomplete,
            CutKind::Truncated => End::Aborted,
            CutKind::Missing => End::Aborted,
            CutKind::Gap => End::Aborted,
            CutKind::End => End::Aborted,
        };
        let _ = State::recover(self, io, reason, at).await;
    }

    async fn on_gap(&mut self, _io: &mut BusIo<Event>, _range: TickRange) {}

    async fn on_end(&mut self, _io: &mut BusIo<Event>, _tick: u64) {}

    async fn on_progress(&mut self, _io: &mut BusIo<Event>, _tick: u64) {}
